 19	type resizedArtworkReader struct {
 20		artID      model.ArtworkID
 21		cacheKey   string
 22		lastUpdate time.Time
 23		size       int
 24		a          *artwork
 25	}
 26	
 27	func resizedFromOriginal(ctx context.Context, a *artwork, artID model.ArtworkID, size int) (*resizedArtworkReader, error) {
 28		r := &resizedArtworkReader{a: a}
 29		r.artID = artID
 30		r.size = size
 31	
 32		// Get lastUpdated and cacheKey from original artwork
 33		original, err := a.getArtworkReader(ctx, artID, 0)
 34		if err != nil {
 35			return nil, err
 36		}
 37		r.cacheKey = original.Key()
 38		r.lastUpdate = original.LastUpdated()
 39		return r, nil
 40	}
 41	
 42	func (a *resizedArtworkReader) Key() string {
 43		return fmt.Sprintf(
 44			"%s.%d.%d",
 45			a.cacheKey,
 46			a.size,
 47			conf.Server.CoverJpegQuality,
 48		)
 49	}
 50	
 51	func (a *resizedArtworkReader) LastUpdated() time.Time {
 52		return a.lastUpdate
 53	}
 54	
 55	func (a *resizedArtworkReader) Reader(ctx context.Context) (io.ReadCloser, string, error) {
 56		// Get artwork in original size, possibly from cache
 57		orig, _, err := a.a.Get(ctx, a.artID, 0)
 58		if err != nil {
 59			return nil, "", err
 60		}
 61	
 62		// Keep a copy of the original data. In case we can't resize it, send it as is
 63		buf := new(bytes.Buffer)
 64		r := io.TeeReader(orig, buf)
 65		defer orig.Close()
 66	
 67		resized, origSize, err := resizeImage(r, a.size)
 68		if resized == nil {
 69			log.Trace(ctx, "Image smaller than requested size", "artID", a.artID, "original", origSize, "resized", a.size)
 70		} else {
 71			log.Trace(ctx, "Resizing artwork", "artID", a.artID, "original", origSize, "resized", a.size)
 72		}
 73		if err != nil {
 74			log.Warn(ctx, "Could not resize image. Will return image as is", "artID", a.artID, "size", a.size, err)
 75		}
 76		if err != nil || resized == nil {
 77			// Force finish reading any remaining data
 78			_, _ = io.Copy(io.Discard, r)
 79			return io.NopCloser(buf), "", nil //nolint:nilerr
 80		}
 81		return io.NopCloser(resized), fmt.Sprintf("%s@%d", a.artID, a.size), nil
 82	}
 83	
 84	func resizeImage(reader io.Reader, size int) (io.Reader, int, error) {
 85		original, format, err := image.Decode(reader)
 86		if err != nil {
 87			return nil, 0, err
 88		}
 89	
 90		bounds := original.Bounds()
 91		originalSize := max(bounds.Max.X, bounds.Max.Y)
 92	
 93		// Don't upscale the image
 94		if originalSize <= size {
 95			return nil, originalSize, nil
 96		}
 97	
 98		resized := imaging.Fit(original, size, size, imaging.Lanczos)
 99	
100		buf := new(bytes.Buffer)
101		if format == "png" {
102			err = png.Encode(buf, resized)
103		} else {
104			err = jpeg.Encode(buf, resized, &jpeg.Options{Quality: conf.Server.CoverJpegQuality})
105		}
106		return buf, originalSize, err
107	}
